from html import escape

def render(r):
    esc=lambda v:escape(str(v),quote=True)
    rows=[]
    for j in r['jobs']:
        hops=' → '.join([j['hops'][0]['source']]+[h['destination'] for h in j['hops']]) if j['hops'] else 'No transfer'
        rows.append('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in (j['id'],j['status'],j['reason_code'] or '—',hops,j.get('arrival_s','—'),j['estimated_cost']))+'</tr>')
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Netcap Orbital</title><style>body{font:16px/1.5 system-ui;background:#f3f6fa;color:#162a40;margin:0}main{max-width:1100px;margin:auto;padding:24px}section{background:white;border:1px solid #b7c6d7;border-radius:10px;padding:20px;margin:20px 0}.scroll{overflow:auto}table{border-collapse:collapse;min-width:700px}td,th{padding:12px;border-bottom:1px solid #ccd8e4;text-align:left}code{overflow-wrap:anywhere}@media(max-width:600px){main{padding:12px}}</style><main><h1>Netcap Orbital</h1><p>Synthetic contact routing and fleet availability · prediction, not flight execution</p><section><h2>Delivery plans</h2><div class="scroll"><table><thead><tr>'''+''.join('<th scope="col">'+x+'</th>' for x in ('Job','Status','Refusal','Route','Arrival (s)','Estimated cost (input currency)'))+'</tr></thead><tbody>'+''.join(rows)+'''</tbody></table></div></section><section><h2>Shared resources</h2><p>Available capacity: '''+esc(r['available_capacity_kw_seconds'])+''' kW-seconds. Planning cost: '''+esc(r['estimated_cost'])+'''. Decimal GB and Gbps. Whole jobs are stored before forwarding. Endpoint terminals and links are shared; refused trials retain no reservations or costs.</p><p>Greedy simple-path search with conservative full-size buffers, no optimality guarantee. Contacts and power are supplied synthetic assumptions; no geometry, weather, regulatory certification or measured reliability is implied. Availability is commissioned state minus declared outages; replacement needs a separate node record.</p></section><section><h2>Reproduce</h2><p>Input <code>'''+esc(r['input_sha256'])+'</code></p><p>Source <code>'+esc(r['source_sha256'] or 'unbound API call')+'</code></p><p>Receipt <code>'+esc(r['receipt_id'])+'</code></p></section></main></html>'
